package com.android.messaging.sms;
import android.content.BroadcastReceiver;import android.content.ContentValues;import android.content.Context;import android.content.Intent;import android.provider.Telephony;import android.telephony.SmsMessage;import android.telephony.SubscriptionManager;import com.android.messaging.util.AppPrefs;import com.android.messaging.util.NotificationHelper;
public final class SmsReceiver extends BroadcastReceiver {@Override public void onReceive(Context c,Intent i){if(i==null||!Telephony.Sms.Intents.SMS_DELIVER_ACTION.equals(i.getAction()))return;PendingResult pr=goAsync();new Thread(()->{try{SmsMessage[]ms=Telephony.Sms.Intents.getMessagesFromIntent(i);if(ms==null||ms.length==0||ms[0]==null)return;SmsMessage first=ms[0];String a=first.getDisplayOriginatingAddress();if(a==null)a=first.getOriginatingAddress();if(a==null)a="Unknown";StringBuilder b=new StringBuilder();for(SmsMessage m:ms)if(m!=null&&m.getMessageBody()!=null)b.append(m.getMessageBody());long now=System.currentTimeMillis(),thread=Telephony.Threads.getOrCreateThreadId(c,a);ContentValues v=new ContentValues();v.put(Telephony.Sms.ADDRESS,a);v.put(Telephony.Sms.BODY,b.toString());v.put(Telephony.Sms.DATE,now);v.put(Telephony.Sms.DATE_SENT,first.getTimestampMillis()>0?first.getTimestampMillis():now);v.put(Telephony.Sms.READ,0);v.put(Telephony.Sms.SEEN,0);v.put(Telephony.Sms.THREAD_ID,thread);v.put(Telephony.Sms.TYPE,Telephony.Sms.MESSAGE_TYPE_INBOX);v.put(Telephony.Sms.PROTOCOL,first.getProtocolIdentifier());int sub=i.getIntExtra(SubscriptionManager.EXTRA_SUBSCRIPTION_INDEX,SubscriptionManager.INVALID_SUBSCRIPTION_ID);if(SubscriptionManager.isValidSubscriptionId(sub))v.put(Telephony.Sms.SUBSCRIPTION_ID,sub);if(c.getContentResolver().insert(Telephony.Sms.Inbox.CONTENT_URI,v)!=null){AppPrefs.archive(c,thread,false);NotificationHelper.incoming(c,a,thread,b.toString());}}catch(Exception ignored){}finally{pr.finish();}},"sms-receive").start();}}
